SELECT 

AND m.session_id = #{sessionId} AND m.id = #{messageId}
LIMIT 1

SELECT 



AND m.session_id = #{sessionId}
AND EXISTS (SELECT 1 FROM ai_agent_working_memory_message anchor
            INNER JOIN ai_agent_working_memory_turn anchor_turn ON anchor_turn.id = anchor.turn_id
            WHERE anchor.id = #{messageId} AND anchor.session_id = #{sessionId}
              AND (t.turn_seq < anchor_turn.turn_seq
                   OR (t.turn_seq = anchor_turn.turn_seq AND m.seq_no < anchor.seq_no)
                   OR (t.turn_seq = anchor_turn.turn_seq AND m.seq_no = anchor.seq_no AND m.id < anchor.id)))
ORDER BY t.turn_seq DESC, m.seq_no DESC, m.id DESC
LIMIT #{limit}

SELECT 



AND m.session_id = #{sessionId}
AND EXISTS (SELECT 1 FROM ai_agent_working_memory_message anchor
            INNER JOIN ai_agent_working_memory_turn anchor_turn ON anchor_turn.id = anchor.turn_id
            WHERE anchor.id = #{messageId} AND anchor.session_id = #{sessionId}
              AND (t.turn_seq > anchor_turn.turn_seq
                   OR (t.turn_seq = anchor_turn.turn_seq AND m.seq_no > anchor.seq_no)
                   OR (t.turn_seq = anchor_turn.turn_seq AND m.seq_no = anchor.seq_no AND m.id > anchor.id)))
ORDER BY t.turn_seq ASC, m.seq_no ASC, m.id ASC
LIMIT #{limit}

SELECT 

AND m.session_id = #{sessionId}
ORDER BY t.turn_seq ASC, m.seq_no ASC, m.id ASC
